#!/usr/bin/env bash
set -euo pipefail
python - <<'PY'
from pathlib import Path

p=Path('apps/api/src/quantnifty/live_paper_manager.py')
s=p.read_text()
if '_decision_audit(' not in s:
    marker='def _risk_levels(entry_spot: float, direction: str, plan: dict[str, Any]) -> dict[str, Any]:\n'
    helper='''def _decision_audit(snapshot: dict[str, Any], decision: dict[str, Any], instrument: dict[str, Any] | None) -> dict[str, Any]:\n    signal = decision.get("signal") or {}; risk = decision.get("risk") or {}; plan = decision.get("execution_plan") or {}; adaptive = signal.get("adaptive") or {}; leg = _leg(snapshot, instrument)\n    return {"captured_at": snapshot.get("timestamp"), "spot": _f(snapshot.get("spot")), "expiry": snapshot.get("expiry"), "market": {k: snapshot.get(k) for k in ("pcr","call_oi","put_oi","call_oi_change","put_oi_change","gex","dex","vanna_proxy","iv_skew","atm_iv","gamma_flip","max_pain","support","resistance","structure","dealer_flow","liquidity_score","bullish_score","bearish_score","bias","confidence")}, "expected_move": snapshot.get("expected_move"), "gamma_walls": snapshot.get("gamma_walls") or [], "selected_option": dict(leg) if isinstance(leg, dict) else dict(instrument or {}), "signal": {k: signal.get(k) for k in ("direction","confidence","scores","evidence","rationale","oi_flow","gamma","dealer","volatility","historical_evidence")}, "adaptive": {k: adaptive.get(k) for k in ("regime","selected_strategy","preferred_direction","readiness_pct","reason","risk_profile","learning")}, "risk": {"approved": bool(risk.get("approved")), "gates": risk.get("gates") or {}, "reasons": risk.get("reasons") or [], "max_risk_pct": risk.get("max_risk_pct")}, "execution_plan": dict(plan), "checklist": {k: bool(v) for k,v in (risk.get("gates") or {}).items()}, "all_required_gates_passed": bool(risk.get("approved"))}\n\n\n'''
    if marker not in s: raise SystemExit('risk-level marker missing')
    s=s.replace(marker,helper+marker,1)
if 'self.entry_audit:' not in s:
    s=s.replace('self.entry_risk: dict[str, Any] = {}; self.entry_trigger', 'self.entry_risk: dict[str, Any] = {}; self.entry_audit: dict[str, Any] = {}; self.entry_trigger',1)
s=s.replace('self.entry_risk = outcome.get("entry_risk")', 'self.entry_audit = outcome.get("entry_audit") if isinstance(outcome.get("entry_audit"), dict) else {}\n        self.entry_risk = outcome.get("entry_risk")',1)
s=s.replace('self.entry_risk = _risk_levels(spot, direction, plan); self.entry_trigger', 'self.entry_risk = _risk_levels(spot, direction, plan); self.entry_audit = _decision_audit(snapshot, decision, instrument); self.entry_trigger',1)
s=s.replace('"entry_risk": self.entry_risk, "entry_trigger"', '"entry_risk": self.entry_risk, "entry_audit": self.entry_audit, "entry_trigger"')
s=s.replace('self.entry_risk = {}; self.entry_trigger = None;', 'self.entry_risk = {}; self.entry_audit = {}; self.entry_trigger = None;',1)
s=s.replace('"entry_reasons": self.entry_reasons, "entry_trigger": self.entry_trigger', '"entry_reasons": self.entry_reasons, "entry_audit": self.entry_audit, "entry_trigger": self.entry_trigger',1)
p.write_text(s)

p=Path('apps/api/src/quantnifty/main.py')
s=p.read_text()
if 'def trade_audit_page' not in s:
    anchor='@app.get("/backtest")\ndef backtest_page():'
    ins='''@app.get("/trade-audit")\ndef trade_audit_page():\n    path=os.path.join(os.path.dirname(__file__),"web","trade_audit.html"); return FileResponse(path)\n\n'''
    if anchor not in s: raise SystemExit('backtest route marker missing')
    s=s.replace(anchor,ins+anchor,1)
if 'def trade_audit_api' not in s:
    anchor='@app.get("/api/v1/learning/status")\ndef learning_status_api(): return learning_status()\n'
    ins='''@app.get("/api/v1/trade-audit")\ndef trade_audit_api(day: str | None = None):\n    from quantnifty.learning_store import load_events\n    selected=str(day or datetime.now(IST).date().isoformat()); rows=[]\n    for event in load_events("outcomes", selected):\n        outcome=event.get("outcome") if isinstance(event,dict) else None\n        if not isinstance(outcome,dict) or not outcome.get("trade_id"): continue\n        rows.append({"trade": outcome, "audit": outcome.get("entry_audit") or {}})\n    return {"mode":"READ_ONLY_PAPER_AUDIT","day":selected,"trading":"DISABLED","trades":rows,"note":"Decision-time evidence is captured at entry and remains immutable; no research/counterfactual data is presented as a trade."}\n\n'''
    if anchor not in s: raise SystemExit('learning status marker missing')
    s=s.replace(anchor,anchor+'\n'+ins,1)
p.write_text(s)

ui=Path('apps/api/src/quantnifty/web/trade_audit.html')
ui.write_text('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>QuantNifty Trade Audit</title><style>body{margin:0;background:#080d19;color:#e8edf7;font:14px Inter,system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:24px}.panel{background:#11182b;border:1px solid #263250;border-radius:14px;padding:16px;margin:12px 0}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.card{background:#0d1425;border:1px solid #263250;border-radius:10px;padding:10px}.label{color:#7d89a4;font-size:10px;text-transform:uppercase}.v{font-weight:800;margin-top:4px}.pass{color:#62e3bc}.fail{color:#ff7180}.muted{color:#7d89a4}.section{margin-top:18px}.json{white-space:pre-wrap;word-break:break-word;background:#0b1120;padding:12px;border-radius:8px;color:#b9c5dc}.check{display:flex;flex-wrap:wrap;gap:8px}.check .card{min-width:180px}@media(max-width:900px){.grid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.grid{grid-template-columns:1fr}}</style></head><body><main><h1>🧠 QuantNifty Trade Audit</h1><div class="muted">Decision-time evidence · immutable entry record · paper only · trading disabled</div><div id="app" class="panel">Loading…</div></main><script>const app=document.getElementById('app');const n=v=>v==null?'—':typeof v==='number'?v.toLocaleString('en-IN',{maximumFractionDigits:4}):String(v);const card=(k,v,c='')=>`<div class="card"><div class="label">${k}</div><div class="v ${c}">${n(v)}</div></div>`;const obj=o=>Object.entries(o||{}).map(([k,v])=>card(k,typeof v==='object'?JSON.stringify(v):v)).join('');function render(d){if(!d.trades.length){app.innerHTML='<div class="muted">No paper trades recorded for '+d.day+'.</div>';return}app.innerHTML=d.trades.map((x,i)=>{const t=x.trade,a=x.audit||{},m=a.market||{},r=a.risk||{},er=a.entry_risk||{},c=a.checklist||{};return `<div class="panel"><h2>Trade #${i+1} · ${n(t.instrument&&t.instrument.trading_symbol)} · ${n(t.status)}</h2><div class="grid">${card('Entry time',t.entry_timestamp)}${card('Entry spot',t.entry_spot)}${card('Entry premium',t.entry_price)}${card('Exit time',t.exit_timestamp)}${card('Exit spot',t.exit_spot)}${card('Exit premium',t.exit_price)}${card('SL',er.stop_spot)}${card('Target',er.target_spot)}${card('R:R',er.risk_reward)}${card('Realized P&L',t.realized_pnl)}${card('Direction',t.direction)}${card('Strategy',a.adaptive&&a.adaptive.selected_strategy)}${card('Trigger',t.entry_trigger)}${card('Exit reason',t.exit_reasons&&t.exit_reasons.exit_reason)}</div><div class="section"><h3>Validation checklist at entry</h3><div class="check">${Object.entries(c).map(([k,v])=>card(k,v?'PASS':'FAIL',v?'pass':'fail')).join('')}</div><p class="muted">All required gates passed: ${a.all_required_gates_passed?'YES':'NO'}</p></div><div class="section"><h3>Decision-time market parameters</h3><div class="grid">${obj(m)}</div></div><div class="section"><h3>Selected option + Greeks / microstructure</h3><div class="grid">${obj(a.selected_option)}</div></div><div class="section"><h3>Brain, Adaptive and institutional evidence</h3><div class="json">${JSON.stringify({signal:a.signal,adaptive:a.adaptive},null,2)}</div></div><div class="section"><h3>Risk / execution decision</h3><div class="json">${JSON.stringify({risk:r,entry_risk:er,execution_plan:a.execution_plan},null,2)}</div></div></div>`}).join('')}fetch('/api/v1/trade-audit?day='+new Date().toISOString().slice(0,10)).then(r=>r.json()).then(render).catch(e=>app.textContent='Audit unavailable: '+e)</script></body></html>''',encoding='utf-8')

Path('apps/api/tests/test_trade_audit.py').write_text('''from quantnifty.live_paper_manager import _decision_audit\n\ndef test_decision_audit_captures_market_greeks_and_checklist():\n    snapshot={"timestamp":"2026-09-11T03:52:07+00:00","spot":23256.8,"pcr":1.1,"gex":-123,"dex":-456,"atm_iv":14.2,"iv_skew":2.1,"gamma_flip":23280,"structure":"BELOW_GAMMA_FLIP","dealer_flow":"CALL_RESISTANCE","liquidity_score":82,"expected_move":{"move":160},"option_chain":[{"security_id":"1","trading_symbol":"NIFTY","strike":23400,"side":"PE","last_price":189,"bid":188,"ask":190,"oi":100000,"previous_oi":90000,"volume":200000,"iv":15,"delta":-0.6,"gamma":0.001,"theta":-5,"vega":10}]}\n    decision={"signal":{"direction":"BEARISH","confidence":72,"scores":{"BEARISH":70},"evidence":["OI flow BEARISH"],"adaptive":{"selected_strategy":"early_accumulation","regime":"NORMAL_ADAPTIVE","preferred_direction":"BEARISH","readiness_pct":72}},"risk":{"approved":True,"gates":{"direction":True,"confidence":True,"liquidity":True,"data_integrity":True}},"execution_plan":{"entry":"EARLY_ACCUMULATION_CONFIRMATION"}}\n    audit=_decision_audit(snapshot,decision,{"security_id":"1","strike":23400,"side":"PE"})\n    assert audit["market"]["gex"]==-123 and audit["market"]["dex"]==-456\n    assert audit["selected_option"]["delta"]==-0.6 and audit["selected_option"]["gamma"]==0.001\n    assert audit["checklist"]=={"direction":True,"confidence":True,"liquidity":True,"data_integrity":True}\n    assert audit["all_required_gates_passed"] is True\n''',encoding='utf-8')

# Add a persistent handoff note without replacing existing history.
h=Path('PROJECT_HANDOFF.md'); hs=h.read_text()
if 'Trade decision audit trail — 2026-09-11' not in hs:
    marker='## Architecture / ownership\n'
    note='''## Trade decision audit trail — 2026-09-11\nEvery newly opened paper trade now captures an immutable `entry_audit` at the exact decision snapshot. The audit contains entry-time market analytics (PCR/OI/OI changes/GEX/DEX/vanna/IV/gamma flip/walls/max pain/expected move/support/resistance/structure/dealer flow/liquidity/bias/scores), the exact selected option row including IV/delta/gamma/theta/vega/OI/volume/bid/ask, Institutional signal scores/evidence, Adaptive regime/strategy/readiness/reason, every risk gate as a PASS/FAIL checklist, and the final execution/risk plan. The evidence is persisted on both OPEN and CLOSED paper outcomes and exposed through read-only `/api/v1/trade-audit` and `/trade-audit`. Exit fields remain empty until a real paper close occurs. This is audit telemetry only; real trading remains disabled.\n\n'''
    if marker in hs: hs=hs.replace(marker,note+marker,1)
    h.write_text(hs)
PY
python -m py_compile apps/api/src/quantnifty/live_paper_manager.py apps/api/src/quantnifty/main.py
python -m pytest -q apps/api/tests/test_trade_audit.py

git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
git add apps/api/src/quantnifty/live_paper_manager.py apps/api/src/quantnifty/main.py apps/api/src/quantnifty/web/trade_audit.html apps/api/tests/test_trade_audit.py PROJECT_HANDOFF.md
git commit -m 'feat: persist and expose trade decision audit'
git push
